/* APS Field App – Handbook scenarios (data only). Add a scenario by pushing one more object onto APS_SCENARIOS.
   Shape:
   { id, title, kw:'search words', sum:'one line',
     diagnose:{ start:'q1', nodes:{ q1:{q:'Question?', hint:'optional', opts:[['Label','nextNodeId'],...]},
                                    r1:{res:1, cause:'Likely cause', why:'optional', do:['what to do',...], parts:[['Button label','parts search words']], call:'electrician|gas|plumber|municipality' (optional red call-out), next:'repair' (optional jump to a tab)} } },
     repair:{ warn:['red warning',...], tools:[...], parts:[[label,query],...], steps:['tick-box step',...], sans:['guide-only standard notes',...], see:['scenario-id','tab','Button label'] },
     install:{ ...same as repair... } }
   Standards named here are for orientation only. Every page shows "Guide only - check the current standard". */
var APS_GOF='Guide only \u2013 check the current standard';
var APS_CALLS={electrician:'Call a registered electrician. Electrical work on a geyser needs an Electrical Certificate of Compliance (CoC).',gas:'Call a registered gas installer. Gas work needs a gas Certificate of Conformity (CoC). Do not repair gas appliances yourself.',plumber:'This needs a licensed (PIRB) plumber.',municipality:'Report it to the municipality / water department.'};
var ELEC_WARN='Geyser wiring, elements and thermostats: a registered electrician only (Electrical CoC). A plumber isolates and makes safe at the DB, tests it is dead, and never switches on a geyser that is not full of water.';
var APS_SCENARIOS=[
{id:'geyser-not-heating',title:'Geyser not heating properly',kw:'geyser not heating hot water cold lukewarm element thermostat trip breaker isolator timer prv valves sediment solar gas heat pump runs out',sum:'Electric geyser: no heat, lukewarm, or runs out fast',
 diagnose:{start:'q1',nodes:{
  q1:{q:'What is the problem with the hot water?',hint:'Start with the one that matches best.',opts:[['No hot water at all (cold at every hot tap)','q_pow'],['Hot, but runs out fast or never gets really hot','q_size'],['Hot flow is weak (trickle) but hot enough','r_flow'],['Hot at some taps, not at one tap','r_tap'],['It is a solar, heat pump, gas or instant geyser','q_var']]},
  q_pow:{q:'Check the DB board. Is the geyser breaker ON and the geyser isolator switch (if any) ON?',hint:'Look only. Never open the geyser cover or touch wiring.',opts:[['Breaker is OFF or has tripped','q_trip'],['Breaker and isolator are ON','q_grid'],['Whole house has no power','r_grid']]},
  q_trip:{q:'Is the DB dry and is there no burning smell? Reset the breaker ONCE. Does it trip again?',opts:[['It trips again (immediately or within hours)','r_earth'],['It stays on','r_onceok'],['Wet DB, burning smell, or hot cables','r_danger']]},
  q_grid:{q:'Is there a geyser timer, smart controller (e.g. Geyserwise) or load-control box fitted?',opts:[['Yes','r_timer'],['No / not sure','q_full']]},
  q_full:{q:'Is the geyser full of water? (Cold taps run, geyser isolating valve is open, no leak or wet drip tray.)',opts:[['No: valve closed, supply off, or leaking','r_empty'],['Yes, it is full','q_pipe']]},
  q_pipe:{q:'Feel the hot outlet pipe coming out of the geyser (carefully, back of the hand). Is it hot?',opts:[['Hot at the geyser but cold at the taps','r_pipe'],['Cold or barely warm at the geyser','r_element']]},
  q_size:{q:'How long has it been like this?',opts:[['Always (more people, bigger demand)','r_size'],['Slowly got worse over months','q_age'],['Suddenly, after a power cut, trip or timer change','q_pow'],['Water is hot but not hot enough','q_thermo']]},
  q_age:{q:'Is the geyser older than about 7 years, or is the water very hard (white scale on taps and kettles)?',opts:[['Yes','r_scale'],['No','q_loss']]},
  q_loss:{q:'Is any hot tap dripping, is there a long uninsulated hot pipe, or are hot pipes in a cold roof or outside wall?',opts:[['Yes','r_loss'],['No','r_element']]},
  q_thermo:{q:'Has anyone changed the temperature setting, or does a smart controller or timer limit the temperature?',opts:[['Yes / maybe','r_setting'],['No','r_thermo']]},
  q_var:{q:'Which type is it?',opts:[['Solar (roof panel, tank above or below)','r_solar'],['Heat pump','r_hp'],['Gas','r_gas'],['Instant (tankless, electric)','r_inst']]},
  r_grid:{res:1,cause:'No power to the property',do:['Check if the neighbours have power (outage or load shedding).','Check the main breaker and earth-leakage switch at the DB. Reset it once only.','If only your house is off and it will not reset, call the electrician or Eskom / municipality.'],call:'electrician'},
  r_earth:{res:1,cause:'Likely an electrical fault on the geyser circuit (failed element or thermostat, wet or burnt wiring)',why:'A breaker that keeps tripping is protecting someone. Do not keep resetting it and do not bypass it.',do:['Leave the geyser breaker OFF and label it: "Do not switch on - fault".','Tell the customer why they have no hot water.','Book a registered electrician to test the element, thermostat and wiring.','Plumber: check the drip tray and safety-valve drain for water leaking onto the electrics.'],call:'electrician',parts:[['Element','geyser element'],['Thermostat','geyser thermostat']],next:'repair'},
  r_onceok:{res:1,cause:'A one-off trip (overload, power surge or a load-shedding spike)',do:['Watch the geyser for the next day. Check hot water is back within a few hours.','If it trips again, treat it as an electrical fault and call an electrician.','Ask about a surge protector or load-control box if it keeps happening after power returns.'],next:'repair'},
  r_danger:{res:1,cause:'Unsafe electrics',do:['Do not touch the DB or the geyser wiring.','Switch off at the main breaker only if you can do it without touching wet or damaged parts.','Tell the customer. Keep everyone away.','Call a registered electrician now.'],call:'electrician'},
  r_timer:{res:1,cause:'Timer or controller is off, in the wrong time slot or faulty',do:['Check the timer / controller display and the schedule. Make sure the ON period is long enough for the geyser size.','Check the controller has power and the right time and date.','Ask the electrician to bypass the controller to prove whether the geyser itself heats.','A smart controller can also block heating. Check its app or settings.'],call:'electrician',next:'repair'},
  r_empty:{res:1,cause:'The geyser is empty or isolated. A dry geyser must not be switched on (the element burns out)',do:['Switch the geyser OFF at the DB first.','Open the geyser cold-feed isolating valve fully.','Open a hot tap in the house until water runs without air.','Look for leaks on the geyser, pipes and drip tray. A leaking cylinder means replacement.','Only when the geyser is full: switch the power back on.'],parts:[['Isolating valve','ball valve 22mm']],next:'repair'},
  r_pipe:{res:1,cause:'Hot water is not reaching the taps: closed valve, airlock, blocked non-return valve or mixer fault',do:['Check any isolating valve on the hot outlet.','Open the hot tap fully and bleed air.','Check mixer cartridges, flexi hoses and crossed hot / cold connections at the problem taps.','Check for a faulty non-return or pressure control valve on the supply (hot flow weak everywhere).'],parts:[['Flexi hose','flexi'],['Cartridge','cartridge']],next:'repair'},
  r_element:{res:1,cause:'Failed element, or the thermostat / thermal cut-out has tripped',why:'The geyser has water and power but stays cold. These are the usual reasons. Only a test can tell which.',do:['Electrician: check the power at the geyser, then test the element and thermostat. Some thermostats have a manual reset button after overheating. Do not press it before the cause is known.','Replace a failed element or thermostat (see Repair).','Check the tank for scale or sludge when it is drained.','If the cylinder is old and leaking or corroded, quote a new geyser instead.'],call:'electrician',parts:[['Element','geyser element'],['Thermostat','geyser thermostat'],['Gasket','geyser gasket']],next:'repair'},
  r_size:{res:1,cause:'The geyser is too small for the demand',do:['Count people, showers and baths a day. A 150 L geyser suits about 2 to 3 people; larger families need 200 to 300 L.','Check the real size and rating on the data plate.','Quote a bigger geyser, a second geyser, or a solar / heat-pump option.','Use a timer so the geyser reheats before peak use.'],parts:[['Geyser','geyser 150l']],next:'install'},
  r_scale:{res:1,cause:'Scale or sludge on the element, or an old element',do:['Flush the geyser (drain through the drain cock to a safe place).','Electrician: check the element. A scaled element is replaced, not cleaned.','Check the sacrificial anode and replace it if used up.','In hard-water areas, use an element made for hard water.','If the cylinder is corroded or leaking, replace the geyser.'],parts:[['Element (hard water)','element hard water'],['Anode','anode'],['Gasket','geyser gasket']],next:'repair'},
  r_loss:{res:1,cause:'Hot water is being lost or cooled before it is used',do:['Fix any dripping hot tap or leaking hot pipe. One drip can waste a lot of hot water.','Insulate hot pipes and the geyser as required.','Check the thermostat setting (about 60 \u00B0C).','Shorten very long runs where practical (a hot-water loop or a second small geyser).'],parts:[['Pipe lagging','lagging'],['Tap cartridges','cartridge']],next:'repair'},
  r_setting:{res:1,cause:'The temperature setting or the controller schedule is limiting heat',do:['Ask who changed it and when.','Electrician sets the thermostat (about 60 \u00B0C) or reviews the smart controller settings.','Do not set it lower than about 60 \u00B0C. Lower temperatures allow bacteria to grow in the tank.'],call:'electrician'},
  r_thermo:{res:1,cause:'A faulty thermostat or element',do:['Electrician tests the thermostat and element.','Replace what has failed (see Repair).','While the geyser is drained, check for scale and the anode.'],call:'electrician',parts:[['Thermostat','geyser thermostat'],['Element','geyser element']],next:'repair'},
  r_flow:{res:1,cause:'Restricted supply to the geyser or the hot side',do:['Check the cold feed isolating valve is fully open.','Check the non-return valve, pressure control valve and any strainer for blockage.','Check the hot water pipe size and any partly closed valve.','Remove and clean the aerator or shower head at the taps.','Measure supply pressure with a gauge at an outside tap.'],parts:[['Pressure control valve','pressure control valve'],['Non-return valve','non return valve']],next:'repair'},
  r_tap:{res:1,cause:'A problem at that tap only',do:['Check the mixer cartridge and the flexi hoses.','Check hot and cold are not crossed.','Check the angle valves are fully open.','Clean the aerator.'],parts:[['Cartridge','cartridge'],['Flexi hose','flexi'],['Angle valve','angle valve']]},
  r_solar:{res:1,cause:'Solar system: weather, panel, pump, controller or the electric back-up element',do:['Check the weather and season. Solar is weaker on cloudy or winter days.','Check the electric back-up (the same checks as an electric geyser: breaker, thermostat, element).','Check the circulation pump and controller (pumped systems) for power and error lights.','Check the panels are clean and not shaded, and look for leaks or air in the system.','Call the solar installer for the panels, pump or controller.'],call:'electrician'},
  r_hp:{res:1,cause:'Heat pump: controller, fan or compressor fault, or a lockout',do:['Check the display for an error code and write it down.','Check power supply and breaker.','Check the air inlet and outlet are clear and the filter is clean.','Call the heat pump installer or the maker with the code.'],call:'electrician'},
  r_gas:{res:1,cause:'Gas geyser: gas supply, ignition, flue or water-flow fault',do:['Check the gas bottle or supply is not empty and the gas valve is open.','If you smell gas: open windows, do not use switches or flames, shut off the gas, leave, and call the gas installer.','Do not open or repair gas appliances yourself.'],call:'gas'},
  r_inst:{res:1,cause:'Instant electric heater: low flow, scaled heating parts, tripped protection or an undersized supply',do:['Check the flow is above the heater\u2019s minimum. Clean aerators and filters.','Check the breaker and the cable size rating with an electrician.','Check for scale in hard-water areas.','Electrician checks the heater itself.'],call:'electrician'}
 }},
 repair:{warn:[ELEC_WARN],tools:['Torch / head-lamp','Hose pipe and bucket','Ladder (roof-space access)','Pressure gauge','Element spanner (electrician)','Multimeter (electrician)','PTFE tape','New gasket / seal','Camera (data plate and photos)'],
  parts:[['Geyser element','geyser element'],['Thermostat','geyser thermostat'],['Flange gasket','geyser gasket'],['Anode','anode'],['Pressure control valve','pressure control valve'],['Vacuum breaker','vacuum breaker'],['Safety valve','safety valve'],['Drain cock','drain cock']],
  steps:['Photograph the data plate (litres, kPa rating, element kW). Write down the fault you found with the Diagnose tab.','Switch the geyser OFF at the DB and at the isolator. Label it "Do not switch on". Test it is dead (electrician).','Close the cold-feed isolating valve. Open a hot tap in the house to let pressure out and air in.','Drain the geyser through the drain cock or a hose to a safe place. The water may be scalding: let it cool or draw hot water off first.','Electrician removes the cover, disconnects the wires and removes the element (element spanner). Photograph the wiring before disconnecting.','Look inside the tank and at the old element. Heavy scale or sludge: flush with the cold feed until the water runs clear. Check the anode.','Fit the new element or thermostat of the same type, rating and length, with a new gasket / seal. Do not over-tighten.','Close the drain. Open the cold-feed valve and fill with a hot tap open until water runs steadily without air. Close the tap.','Check the flange, element joint and every pipe joint for leaks while the geyser is filling.','Only when the geyser is FULL: the electrician reconnects, tests, sets the thermostat (usually about 60 \u00B0C) and gives the Electrical CoC.','Check the safety-valve drain and tray: no drips, discharge visible. Briefly lift the valve lever (water must flow, then stop).','Check hot water at the tap after a few hours. Take photos. Tell the customer what was found.'],
  sans:['SANS 10254 covers fixed electric storage water heaters: valves, drip tray, safety (T&P) valve and its drain pipe.','Safety valve drain: metal, at least the valve outlet size, continuous fall with no upward sections, no more than 3 bends, discharging where it can be seen, and with no valve, cap or plug in it.','Vacuum breaker(s) above the top of the geyser; isolating and non-return valves on the cold feed; a pressure control valve where supply pressure is above the geyser rating.','The wiring code for the electrical part is SANS 10142-1. The electrician issues the Electrical CoC.']},
 install:{see:['geyser-install','install','Open "Geyser installation" for the full replacement steps'],warn:['If the cylinder is leaking or corroded, repair is not possible. The geyser must be replaced.'],
  steps:['Compare the repair cost with the age of the geyser. After about 8 to 10 years, or with a leaking cylinder, quote a replacement.','Check the data plate for size and pressure rating so the replacement matches the demand.','Follow the Geyser installation scenario.'],
  parts:[['Geyser','geyser 150l'],['Geyser tray','geyser tray']],
  sans:['Replacement of a geyser normally needs a plumbing CoC from a licensed plumber and an Electrical CoC from an electrician. Insurers often ask for them.']}},
{id:'no-hot-water',title:'No hot water',kw:'no hot water cold geyser breaker tripped timer isolating valve mixer',sum:'First checks when nothing is hot',
 diagnose:{start:'q1',nodes:{
  q1:{q:'Is the water cold at ALL hot taps in the house?',opts:[['Yes, every hot tap','q2'],['Only one tap or one bathroom','r_tap']]},
  q2:{q:'Is there normal cold water pressure at the taps?',opts:[['Yes, cold water is fine','q3'],['No water or very low','r_water']]},
  q3:{q:'Is the geyser breaker (and isolator, if any) ON at the DB?',hint:'Look, do not touch wiring.',opts:[['OFF or tripped','r_trip'],['ON','q4'],['Whole house has no power','r_grid']]},
  q4:{q:'Is there a timer or smart controller on the geyser?',opts:[['Yes','r_timer'],['No / not sure','q5']]},
  q5:{q:'Is the geyser leaking or is the drip tray wet, or is the cold-feed isolating valve closed?',opts:[['Yes','r_empty'],['No, all dry and open','r_elec']]},
  r_tap:{res:1,cause:'Mixer, cartridge, flexi hose or crossed hot / cold at that tap',do:['Check the angle valves are open.','Check the flexi hoses and cartridge.','Clean the aerator.'],parts:[['Cartridge','cartridge'],['Flexi hose','flexi']]},
  r_water:{res:1,cause:'A water supply problem, not a geyser problem',do:['Check the municipal supply and the main valve.','Check the meter and the pressure control valve.'],next:'repair'},
  r_trip:{res:1,cause:'The geyser circuit has tripped or been switched off',do:['Reset the breaker once only (dry DB, no burning smell).','If it trips again, leave it off and call an electrician. Do not keep resetting.','Check the drip tray and wiring for water.'],call:'electrician',next:'repair'},
  r_grid:{res:1,cause:'No power to the property',do:['Check for a local outage or load shedding.','Check the main breaker and earth-leakage switch at the DB.'],call:'electrician'},
  r_timer:{res:1,cause:'Timer or controller is off or in the wrong time slot',do:['Check the schedule and the time on the controller.','Ask the electrician to bypass it to test the geyser.'],call:'electrician',next:'repair'},
  r_empty:{res:1,cause:'The geyser is empty or isolated, or leaking',do:['Switch the geyser off at the DB.','Open the cold-feed isolating valve.','Open a hot tap until water runs without air. Only then switch on.','If the cylinder is leaking, it has to be replaced.'],next:'repair'},
  r_elec:{res:1,cause:'Failed element or thermostat (water and power are fine)',do:['Electrician tests the element and thermostat.','Replace the part that failed.'],call:'electrician',parts:[['Element','geyser element'],['Thermostat','geyser thermostat']],next:'repair'}
 }},
 repair:{warn:[ELEC_WARN],tools:['Torch','Hose and bucket','PTFE tape','Camera'],steps:['Confirm the geyser is full: open a hot tap and check water runs without air.','Check the cold-feed isolating valve is fully open.','Check the breaker and isolator at the DB. Reset a tripped breaker once only.','Check the timer or controller.','Look for leaks at the geyser, pipes and drip tray.','If the geyser has power and water but stays cold, book the electrician to test the element and thermostat.','After the fix, check hot water at a tap after a few hours and tell the customer what was found.'],
  parts:[['Isolating valve','ball valve 22mm'],['Geyser element','geyser element'],['Thermostat','geyser thermostat']],sans:['Never switch on a geyser that is not full of water: the element burns out.','Reconnection of the geyser to power after repairs is for a registered electrician (Electrical CoC).'],see:['geyser-not-heating','diagnose','More detail: "Geyser not heating properly"']}},
{id:'low-pressure',title:'Low water pressure',kw:'low pressure weak flow trickle slow isolating valve blocked aerator pressure control valve galvanised',sum:'Weak flow at one tap, hot only, or the whole house',
 diagnose:{start:'q1',nodes:{
  q1:{q:'Where is the pressure low?',opts:[['Every tap, hot and cold','q_all'],['Only hot water','r_hot'],['One tap or shower only','r_one'],['Only at certain times of day','r_peak']]},
  q_all:{q:'Is the outside tap at the street or meter also weak?',opts:[['Yes, weak at the meter too','r_muni'],['No, strong at the meter','q_pipes']]},
  q_pipes:{q:'Is the house old, with galvanised pipes, or has a valve or pressure control valve been fitted recently?',opts:[['Old galvanised pipes','r_galv'],['New valve or PCV work','r_valve'],['No change, got worse slowly','r_scale']]},
  r_hot:{res:1,cause:'Restricted geyser valves or hot pipe',do:['Check the non-return valve, pressure control valve and strainer on the geyser supply.','Check the isolating valve is fully open.','Check pipe size and any kinks.'],parts:[['Pressure control valve','pressure control valve'],['Non-return valve','non return valve']],next:'repair'},
  r_one:{res:1,cause:'Blocked aerator, shower head, flexi hose or partly closed angle valve',do:['Unscrew and clean the aerator or shower head (vinegar for scale).','Replace the flexi hose if it is kinked or blocked.','Open the angle valve fully.','Check the cartridge.'],parts:[['Flexi hose','flexi'],['Angle valve','angle valve'],['Shower head','shower head']],next:'repair'},
  r_peak:{res:1,cause:'Peak demand in the area',do:['Test with a pressure gauge in the morning, afternoon and evening.','If it drops a lot, quote a tank with a booster pump.'],parts:[['Pressure gauge','pressure gauge']]},
  r_muni:{res:1,cause:'Low supply from the municipality or a faulty water meter or main valve',do:['Check the meter valve and stop-cock are fully open.','Check the meter strainer.','If everyone in the street has it, report it to the municipality.'],call:'municipality'},
  r_galv:{res:1,cause:'Corroded galvanised pipe (scale narrows the bore)',do:['Cut a section open and look inside.','Quote replacing the pipe in copper, PEX or multilayer.'],parts:[['Copper pipe 22mm','copper pipe 22mm'],['Multilayer pipe','multilayer pipe']]},
  r_valve:{res:1,cause:'A valve that is partly closed, set wrong or blocked',do:['Open the isolating valves fully.','Check the PCV setting and clean its strainer.','Check the flow direction arrow on every valve.'],parts:[['Pressure control valve','pressure control valve']],next:'repair'},
  r_scale:{res:1,cause:'Scale or sediment building up in pipes or valves',do:['Flush the system.','Check the strainers and valves.','If it gets worse, camera or cut-out inspection and a quote to replace the worst pipe.'],next:'repair'}
 }},
 repair:{tools:['Pressure gauge (with hose tap adaptor)','Spanners','PTFE tape','Bucket','Pipe cutter'],parts:[['Flexi hose','flexi'],['Angle valve','angle valve'],['Pressure control valve','pressure control valve'],['Shower head','shower head']],
  steps:['Fit the pressure gauge to an outside tap with all taps closed. Note the static pressure.','Open a tap and note the pressure while water runs. A big drop shows a restriction.','Test at the meter side and at the house side to find where it drops.','Clean aerators and shower heads. Replace blocked flexi hoses.','Open all isolating valves fully. Clean strainers in valves.','Replace a faulty pressure control valve. Set it to the geyser rating.','Retest the pressure and flow. Write the readings down for the customer.'],
  sans:['SANS 10252-1 covers water installations. Typical domestic supply pressure is roughly 100 to 400 kPa. Check geyser and fitting ratings before setting a PCV.']}},
{id:'leaking-tap',title:'Leaking tap',kw:'leaking tap dripping drip washer cartridge o-ring spindle basin mixer bibcock',sum:'Drip from the spout, base or handle',
 diagnose:{start:'q1',nodes:{
  q1:{q:'Where does it leak from?',opts:[['Drips from the spout when closed','q_type'],['Water at the base or around the handle','r_oring'],['Under the basin or sink (pipes and hoses)','r_under'],['Outside tap or garden tap','r_out']]},
  q_type:{q:'What kind of tap is it?',opts:[['Old style with two separate taps (washer type)','r_washer'],['Quarter-turn / ceramic disc tap','r_disc'],['Single-lever mixer','r_cart']]},
  r_washer:{res:1,cause:'Worn tap washer or seat',do:['Close the angle valve, open the tap to empty it.','Remove the head, replace the washer. If the seat is pitted, reface or replace it.','Reassemble and test.'],parts:[['Tap washers','tap washer'],['Tap seat','tap seat']],next:'repair'},
  r_disc:{res:1,cause:'Worn ceramic disc / cartridge',do:['Close the water. Remove the head and unscrew the cartridge.','Replace with the same type and length.'],parts:[['Quarter-turn cartridge','cartridge']],next:'repair'},
  r_cart:{res:1,cause:'Worn mixer cartridge',do:['Close the angle valves. Remove the lever, cap and retaining nut.','Replace the cartridge (match 35 mm or 40 mm size and make).','Check the seals and the aerator.'],parts:[['Mixer cartridge','mixer cartridge'],['Basin mixer','basin mixer']],next:'repair'},
  r_oring:{res:1,cause:'Worn spindle seal or O-ring, or a loose gland nut',do:['Close the water. Remove the handle or lever.','Replace the O-ring or gland packing. Tighten the gland nut gently.'],parts:[['O-rings','o-ring'],['Cartridge','cartridge']],next:'repair'},
  r_under:{res:1,cause:'Leaking flexi hose, angle valve or trap joint',do:['Dry everything and watch to find the wet joint.','Replace a leaking flexi hose or angle valve.','Remake trap joints with good seals.'],parts:[['Flexi hose','flexi'],['Angle valve','angle valve'],['Basin trap','basin trap']],next:'repair'},
  r_out:{res:1,cause:'Worn washer or spindle on an outside tap, or a damaged tap',do:['Close the water to the tap. Replace the washer or the bibcock.','Fit a vacuum breaker or a check valve where required.'],parts:[['Bibcock','bibcock'],['Vacuum breaker','vacuum breaker']],next:'repair'}
 }},
 repair:{tools:['Adjustable spanner','Basin spanner','Screwdrivers','Allen keys','Bucket and towel','PTFE tape','Spare washers and O-rings'],parts:[['Cartridge','cartridge'],['Tap washer','tap washer'],['Flexi hose','flexi'],['Angle valve','angle valve']],
  steps:['Close the angle valve under the basin or sink. If there is none, close the room valve or the main and fit angle valves.','Open the tap to release pressure and empty the line.','Put the plug in or a cloth over the drain so small parts do not fall in.','Remove the handle, cap and retaining nut. Take the old cartridge or washer with you to match the new one.','Clean the seat and the body. Fit the new washer or cartridge with grease on the seals.','Reassemble. Do not over-tighten (ceramic cracks).','Open the angle valve slowly. Check the spout, the base and every joint for leaks. Wipe dry and check again after 10 minutes.'],
  sans:['SANS 10252-1: an isolating (angle) valve at each fixture makes repairs easier and is good practice.']}},
{id:'running-toilet',title:'Running toilet',kw:'running toilet cistern float valve fill flush valve seal inlet leaking wc overflow phantom flush',sum:'Water keeps running or trickling into the bowl',
 diagnose:{start:'q1',nodes:{
  q1:{q:'What happens?',opts:[['Water trickles into the bowl all the time','q_dye'],['Water runs into the overflow pipe','r_float'],['Cistern fills very slowly','r_slow'],['Toilet flushes by itself now and then','r_dye'],['Water on the floor','r_floor']]},
  q_dye:{q:'Put food colouring in the cistern. After 10 minutes, is there colour in the bowl without flushing?',opts:[['Yes, colour in the bowl','r_dye'],['No colour. Water level is too high','r_float']]},
  r_dye:{res:1,cause:'Flush valve seal (washer) is perished or dirty',do:['Close the angle valve and flush to empty the cistern.','Clean the seat. Replace the flush valve seal or the whole flush valve.'],parts:[['Flush valve','flush valve'],['Cistern washer','cistern washer']],next:'repair'},
  r_float:{res:1,cause:'Fill valve (float) set too high or faulty',do:['Adjust the float so the water stops about 25 mm below the overflow.','Replace the fill valve if it will not shut off.'],parts:[['Fill valve','fill valve'],['Float valve','float valve']],next:'repair'},
  r_slow:{res:1,cause:'Blocked inlet filter, partly closed angle valve, or a worn fill valve',do:['Check the angle valve is fully open.','Clean the inlet filter on the fill valve.','Replace the fill valve if the flow is still weak.'],parts:[['Fill valve','fill valve'],['Angle valve','angle valve']],next:'repair'},
  r_floor:{res:1,cause:'Leaking cistern connection, cracked cistern or loose flexi hose',do:['Dry everything and watch to find the wet joint.','Check the flexi hose, the angle valve and the cistern inlet nut.','Check the cistern to pan seal and the flush pipe.','A cracked cistern or pan must be replaced.'],parts:[['Flexi hose','flexi'],['Cistern seal','cistern seal']],next:'repair'}
 }},
 repair:{tools:['Adjustable spanner','Screwdrivers','Sponge and bucket','Food colouring','PTFE tape','Spare seals'],parts:[['Fill valve','fill valve'],['Flush valve','flush valve'],['Flexi hose','flexi'],['Angle valve','angle valve']],
  steps:['Close the angle valve behind the toilet. Flush to empty the cistern. Sponge out the rest.','Take photos of how the old parts fit (cistern models differ).','Replace the faulty part: fill valve, flush valve or seal. Match the brand and model where possible.','Reconnect the water. Set the water level about 25 mm below the overflow.','Flush several times. Check the shut-off, the flush volume and every joint for leaks.','Check the cistern to pan connection and the flexi hose are dry. Wipe and check again after 10 minutes.'],
  sans:['SANS 10252-1: cisterns must have an overflow that discharges safely and a fill valve that stops the inflow.','A running toilet can waste a large volume of water in a day. Tell the customer.']}},
{id:'blocked-drain',title:'Blocked drain or gully',kw:'blocked drain gully slow drain rodding eye rods jetter manhole smell gurgling roots grease basin sink bath shower',sum:'Slow or blocked basin, sink, shower, gully or main drain',
 diagnose:{start:'q1',nodes:{
  q1:{q:'What is blocked?',opts:[['One fixture (basin, sink, shower or bath)','r_one'],['Several fixtures, or a gully overflowing','q_main'],['Gurgling noises or smells, but still draining','r_vent'],['The toilet (WC)','r_wc']]},
  q_main:{q:'Open the nearest rodding eye or inspection chamber (slowly, face away). Is it full of water?',opts:[['Full of water: blockage is downstream','r_down'],['Empty or dry: blockage is upstream','r_up']]},
  r_one:{res:1,cause:'Blocked trap or branch (hair, soap, grease)',do:['Put a bucket under. Unscrew the trap and clean it.','Rod or plunge the branch pipe.','Remake the trap with sound seals.'],parts:[['Basin trap','basin trap'],['Bottle trap','bottle trap']],next:'repair'},
  r_up:{res:1,cause:'Blockage between the last full point and this chamber',do:['Rod from this chamber back up the line.','Flush with water and check the line runs clear.'],parts:[['Drain rods','drain rod']],next:'repair'},
  r_down:{res:1,cause:'Blockage downstream of this chamber (main drain or connection)',do:['Rod or jet from this chamber toward the municipal connection.','If it keeps blocking, use a drain camera: roots, a collapse or a belly in the pipe.','Do not enter manholes (gas).'],parts:[['Drain rods','drain rod']],next:'repair'},
  r_vent:{res:1,cause:'Partial blockage, or a blocked or missing vent, or a trap that is too far from a vent',do:['Clear the drain.','Check the vent pipe is open and not blocked.','Check trap distance to the vent and the pipe size.'],parts:[['Air admittance valve','air admittance valve']],next:'repair'},
  r_wc:{res:1,cause:'Blocked toilet',do:['Use the Blocked toilet scenario.'],next:'repair'}
 }},
 repair:{warn:['Never enter a manhole or sewer chamber (gas). Do not mix drain-cleaning chemicals.'],tools:['Gloves and glasses','Bucket and rags','Drain rods','Plunger','Drain machine (if available)','Torch','Disinfectant'],parts:[['Basin trap','basin trap'],['Bottle trap','bottle trap'],['Drain rods','drain rod'],['Gully trap','gully']],
  steps:['Ask which fixtures are blocked. One fixture means a trap or branch. Several means the main drain.','Wear waterproof gloves and glasses. Protect the floor.','Basin or sink: bucket under, unscrew the trap and clean it. Reassemble with sound seals.','Gully or main drain: lift the grid and remove silt and rubbish. Open the nearest rodding eye slowly, face away.','Find where the water stops: flow before the blockage, dry after.','Rod or machine from the open point toward the blockage. Work gently and do not force rods in a bend.','Flush with plenty of water to check the line is free.','If it blocks again, or the pipe is cracked, collapsed or full of roots: camera inspection and a quote for repair.','Disinfect the area and tools. Photograph the cause. Advise the customer (no grease or wipes down the drain).'],
  sans:['SANS 10252-2 covers drainage: access (rodding eyes) where pipes can be cleared, traps with water seals, falls (minimum 1:46 for waste branches and 1:40 for soil branches) and venting.']}},
{id:'blocked-toilet',title:'Blocked toilet',kw:'blocked toilet wc plunger auger closet pan overflow flush',sum:'Toilet will not flush away or is overflowing',
 diagnose:{start:'q1',nodes:{
  q1:{q:'Is the water rising and about to overflow?',opts:[['Yes, close to overflowing','r_stop'],['No, level is stable and drains slowly','q2']]},
  q2:{q:'Do other fixtures (basin, shower, other toilets) drain slowly or gurgle?',opts:[['Yes, others too','r_main'],['No, only this toilet','r_pan']]},
  r_stop:{res:1,cause:'Blockage in the pan or trap. Stop more water going in first',do:['Close the angle valve behind the toilet. Lift the float if you must to stop the cistern filling.','Do not flush again.','Protect the floor. Then clear it (see Repair).'],next:'repair'},
  r_pan:{res:1,cause:'Blockage in the pan trap or just beyond it',do:['Use a flange plunger first.','Then a closet auger if the plunger does not clear it.','Do not use harsh chemicals.'],next:'repair'},
  r_main:{res:1,cause:'Blockage in the branch or main drain, not only the toilet',do:['Open the nearest rodding eye or inspection chamber (face away).','Rod or jet the line.','Use the Blocked drain scenario.'],next:'repair'}
 }},
 repair:{warn:['Wear waterproof gloves and glasses. Do not mix drain-cleaning chemicals. Never enter a manhole.'],tools:['Gloves and glasses','Flange plunger','Closet auger','Old towels and bucket','Disinfectant'],parts:[['WC connector','wc connector'],['Cistern washer','cistern washer']],
  steps:['Close the angle valve behind the toilet. Put towels and a plastic sheet down.','Fit the plunger so it seals in the bowl outlet. Push gently first (air), then pump 10 to 15 times.','If it does not clear, use the closet auger: feed it in, turn the handle and push until it breaks the blockage.','Flush with a bucket of water first. Then flush normally and watch the level.','If it keeps blocking, look for a toy, wipes or a cracked pipe. Lift the pan if needed and inspect the outlet.','If several fixtures are affected, rod the main drain from a rodding eye.','Disinfect the floor, tools and your gloves. Advise the customer: no wipes, nappies or sanitary products in the toilet.'],
  sans:['SANS 10252-2: the pan trap must hold its water seal and the soil pipe must have enough fall (minimum 1:40 for soil branches) and venting.'],see:['blocked-drain','diagnose','Several fixtures blocked? Open "Blocked drain or gully"']}},
{id:'burst-pipe',title:'Burst pipe emergency',kw:'burst pipe emergency flood water off main valve isolate damage leak ceiling',sum:'Water everywhere: stop it first',
 diagnose:{start:'q1',nodes:{
  q1:{q:'Is water flowing now and causing damage?',opts:[['Yes, flooding','r_stop'],['No, it has stopped or is a slow leak','q_where']]},
  q_where:{q:'Can you see where the water comes from?',opts:[['Yes, a visible pipe or joint','r_vis'],['No, inside a wall, ceiling or floor','r_hidden'],['Near the geyser','r_geyser']]},
  r_stop:{res:1,cause:'Stop the water first',do:['Close the main isolating valve (at the meter or house inlet).','Open the lowest tap to drain the system. Open the highest tap to let air in.','If water is near electrics, switch off the main breaker only if it is safe to reach. Otherwise keep away and call an electrician.','If it is the geyser, also close the geyser cold-feed valve and switch off the geyser at the DB.','Take photos of the damage for the insurance.'],next:'repair'},
  r_vis:{res:1,cause:'Failed pipe, joint or fitting',do:['Isolate the section.','Cut out the damaged piece and repair with the correct fitting for the pipe type.','Pressure test.'],next:'repair'},
  r_hidden:{res:1,cause:'Hidden leak',do:['Do a meter test with all taps closed.','Isolate sections to find the leaking branch.','Open the wall or ceiling as little as possible.'],next:'repair'},
  r_geyser:{res:1,cause:'Geyser, valve or pipe leak',do:['Switch off the geyser at the DB. Close the cold-feed valve.','Find the leak: cylinder, safety valve drain, joint or element flange.','A leaking cylinder means the geyser must be replaced.'],next:'repair'}
 }},
 repair:{warn:['Water and electricity: if the DB or sockets are wet, do not touch them. Keep people away and call an electrician.'],tools:['Main isolating key / spanner','Bucket and towels','Wet vacuum','Pipe cutter','Repair couplings','Torch'],parts:[['Repair coupling','repair coupling'],['Copper coupling 22mm','copper coupling 22mm'],['Isolating valve','ball valve'],['Multilayer pipe fittings','multilayer']],
  steps:['Close the main isolating valve. Open the lowest tap to drain, the highest to let air in.','Make electrics safe: switch off the geyser; stay away from a wet DB.','Move people, pets and valuables away. Mop up and ventilate.','Photograph the damage and the burst pipe before you move it.','Cut out the damaged section back to sound pipe.','Fit the correct repair fitting for the pipe type (compression, push-fit, soldered). No tape-and-hope.','Support the pipe properly with clips.','Refill slowly, bleed air and pressure test for at least 15 minutes.','Check the meter with all taps closed: no movement.','Tell the customer what is covered by insurance, what dries out and who does making good.'],
  sans:['SANS 10252-1: pipes must be supported and joined with fittings suited to the pipe material, and tested before being covered.']}},
{id:'geyser-dripping',title:'Geyser dripping / PRV weeping',kw:'geyser dripping safety valve prv weeping t&p drain pipe pressure expansion vacuum breaker tray overflow',sum:'Water from the safety valve drain or the drip tray',
 diagnose:{start:'q1',nodes:{
  q1:{q:'Where is the water coming from?',opts:[['The safety valve drain pipe (outside)','q_amt'],['The drip tray under the geyser','q_tray'],['The vacuum breaker','r_vb'],['A pipe joint on or near the geyser','r_joint']]},
  q_amt:{q:'How much water comes out?',opts:[['A few drips, mostly while the geyser heats','r_exp'],['A steady drip or a stream all the time','q_press']]},
  q_press:{q:'Measure supply pressure with a gauge. Is it above the geyser rating (typically 200, 300 or 400 kPa)?',opts:[['Yes, pressure is too high','r_press'],['No, pressure is within the rating','q_hot']]},
  q_hot:{q:'Is the water at the taps scalding hot, or is the geyser hotter than normal?',opts:[['Yes, scalding or very hot','r_hot'],['No, normal','r_valve']]},
  q_tray:{q:'Is the water coming from the geyser body or from the pipes above the tray?',opts:[['From the geyser body (rust, weeping)','r_cyl'],['From a pipe or valve above the tray','r_joint']]},
  r_exp:{res:1,cause:'Thermal expansion in a closed (non-return valve) system',do:['A small drip while heating is common in a closed system.','If it is more than a small drip, check the pressure and the expansion arrangement the maker requires.','Do not block the drain pipe.'],next:'repair'},
  r_press:{res:1,cause:'Supply pressure too high for the geyser',do:['Fit a pressure control valve set below the geyser rating.','Check the PCV setting if one is already fitted.','Check the pressure again.'],parts:[['Pressure control valve','pressure control valve']],next:'repair'},
  r_hot:{res:1,cause:'Geyser overheating: thermostat or controller fault',do:['Switch the geyser off at the DB. This is urgent: scald and pressure risk.','Electrician checks the thermostat and cut-out.','Check the safety valve works (lift the lever briefly).'],call:'electrician',parts:[['Thermostat','geyser thermostat']],next:'repair'},
  r_valve:{res:1,cause:'Faulty or dirty T&P safety valve',do:['Lift the lever briefly to flush the seat. Let it snap closed.','If it still drips, replace the valve with one of the right pressure rating.'],parts:[['Safety valve','safety valve']],next:'repair'},
  r_vb:{res:1,cause:'Vacuum breaker leaking or faulty',do:['Check the seat for dirt. Replace the vacuum breaker if it keeps leaking.','Check supply pressure is not too high.'],parts:[['Vacuum breaker','vacuum breaker']],next:'repair'},
  r_joint:{res:1,cause:'A joint, valve or pipe leaking',do:['Isolate and dry the area. Watch to find the wet joint.','Remake the joint with new seals or replace the fitting.'],parts:[['Geyser connector','geyser connector']],next:'repair'},
  r_cyl:{res:1,cause:'Corroded cylinder',do:['Isolate the water and the power.','The geyser is finished. Quote a replacement.','Put a bucket and tray to limit damage.'],parts:[['Geyser','geyser 150l']],next:'install'}
 }},
 repair:{warn:[ELEC_WARN],tools:['Pressure gauge','Spanners','PTFE tape','Torch','Hose and bucket'],parts:[['Pressure control valve','pressure control valve'],['Safety (T&P) valve','safety valve'],['Vacuum breaker','vacuum breaker'],['Drip tray','geyser tray']],
  steps:['Measure the supply pressure with a gauge at an outside tap. Write it down and compare with the geyser rating.','Check what is dripping: safety valve drain, vacuum breaker, a joint or the tray.','Lift the safety valve lever briefly. Water must flow and then stop. Never block the drain.','If the pressure is high: fit or reset a pressure control valve to below the geyser rating.','If the valve is faulty: isolate the water, drain down, replace the T&P valve with the same pressure rating and thread.','Check the safety valve drain pipe: metal, continuous fall, no more than 3 bends, no valves or plugs.','Check the drip tray drain and fix the cause of any water in it.','Check again after a day. Tell the customer what was wrong.'],
  sans:['SANS 10254: safety valve drain pipe is metal, at least the size of the valve outlet, with a continuous fall, no more than 3 bends, and discharges where it can be seen. No valve, cap or plug in the drain.','Fit a drip tray with its own drain pipe where a leak can cause damage.']},
 install:{see:['geyser-install','install','Open "Geyser installation / replacement"'],steps:['A corroded cylinder cannot be repaired: quote a new geyser.','Follow the Geyser installation scenario for the valves, tray and safety drain.'],sans:['A new geyser needs a plumbing CoC from a licensed plumber and an Electrical CoC from an electrician where required.']}},
{id:'noisy-pipes',title:'Noisy pipes / water hammer',kw:'noisy pipes water hammer banging clicking whistle vibrating rattle arrester',sum:'Bang, click, whistle or rattle in the pipes',
 diagnose:{start:'q1',nodes:{
  q1:{q:'What sort of noise is it?',opts:[['A bang when a tap or valve closes','r_ham'],['Clicking or ticking when the geyser heats','r_click'],['Whistling or squealing','r_whistle'],['Rattle or vibration','r_rattle'],['Banging when the cistern fills','r_fill'],['Noise from the pump','r_pump']]},
  r_ham:{res:1,cause:'Water hammer: high pressure, fast-closing valves or loose pipes',do:['Measure supply pressure. Fit or set a pressure control valve if it is high.','Clip loose pipes.','Fit a water hammer arrester near the noisy valve or appliance.'],parts:[['Water hammer arrester','water hammer arrester'],['Pressure control valve','pressure control valve']],next:'repair'},
  r_click:{res:1,cause:'Pipes expanding and rubbing in clips or sleeves',do:['Loosen or pad the clips. Add sleeves where pipes pass through walls.'],parts:[['Pipe clips','pipe clip'],['Pipe lagging','lagging']],next:'repair'},
  r_whistle:{res:1,cause:'A partly closed valve, worn washer or cartridge, or high flow',do:['Open valves fully.','Replace worn washers or cartridges.','Check the pressure.'],parts:[['Cartridge','cartridge'],['Tap washer','tap washer']],next:'repair'},
  r_rattle:{res:1,cause:'Pipes touching walls or each other',do:['Add clips and pads.','Support long runs.'],parts:[['Pipe clips','pipe clip']],next:'repair'},
  r_fill:{res:1,cause:'Faulty or worn cistern fill valve',do:['Replace the fill valve.'],parts:[['Fill valve','fill valve']]},
  r_pump:{res:1,cause:'Air in the pump or poor mountings',do:['Bleed the air.','Check the mounting pads and the pipe connections.','Check the pump pressure settings.'],parts:[['Pump','pump']]}
 }},
 repair:{tools:['Pressure gauge','Pipe clips and screws','Pipe insulation','Spanners','Hacksaw or pipe cutter'],parts:[['Water hammer arrester','water hammer arrester'],['Pressure control valve','pressure control valve'],['Pipe clips','pipe clip'],['Pipe lagging','lagging']],
  steps:['Find where the noise starts: open and close the taps one at a time.','Measure the supply pressure. High pressure makes water hammer worse.','Clip every loose pipe. Add pads where pipes touch.','Fit a water hammer arrester close to the quick-closing valve or machine.','Replace worn washers and cartridges that whistle.','Check again with all taps and appliances. Note what was done.'],
  sans:['SANS 10252-1 covers pipe support and pressure in water installations. Check the maker\u2019s data for pressure control valve settings.']}},
{id:'hot-too-hot-cold',title:'Hot water too hot or too cold',kw:'hot water too hot scald cold temperature thermostat mixing valve 60 legionella',sum:'Scalding hot, or never really hot',
 diagnose:{start:'q1',nodes:{
  q1:{q:'What is the problem?',opts:[['Water is scalding hot at the taps','q_hot'],['Water is only warm or lukewarm','q_warm']]},
  q_hot:{q:'Is the safety valve dripping or is the geyser making steam or boiling noises?',opts:[['Yes','r_danger'],['No, just very hot at the tap','r_set']]},
  q_warm:{q:'Is the thermostat set to about 60 \u00B0C and is the geyser big enough?',opts:[['Setting is low','r_low'],['Setting is right, geyser is big enough','r_elem'],['Not sure','r_elem']]},
  r_danger:{res:1,cause:'Geyser overheating: thermostat or cut-out fault. This is dangerous (scalding and pressure)',do:['Switch the geyser OFF at the DB now.','Do not draw very hot water for the children. Warn the customer.','Check the safety valve is working and the drain is clear.','Electrician checks the thermostat and cut-out.'],call:'electrician',next:'repair'},
  r_set:{res:1,cause:'Thermostat is set too high, or there is no mixing protection',do:['Electrician sets the thermostat to about 60 \u00B0C.','Fit a thermostatic mixing valve at showers and baths for children and the elderly.','Warn the customer about scalding.'],call:'electrician',parts:[['Thermostatic mixing valve','thermostatic mixing valve']],next:'repair'},
  r_low:{res:1,cause:'Thermostat or controller set too low',do:['Electrician sets the thermostat to about 60 \u00B0C.','Do not keep the tank below about 60 \u00B0C: bacteria (legionella) can grow.'],call:'electrician'},
  r_elem:{res:1,cause:'Failing element or thermostat, or a small geyser',do:['Follow the Geyser not heating scenario.'],call:'electrician',next:'repair'}
 }},
 repair:{warn:['A geyser that boils or is much too hot can scald and can burst. Switch it off at the DB and call an electrician.',ELEC_WARN],tools:['Thermometer','Torch','Spanners'],parts:[['Thermostatic mixing valve','thermostatic mixing valve'],['Geyser thermostat','geyser thermostat'],['Safety valve','safety valve']],
  steps:['Measure the water temperature at the tap with a thermometer after it runs for a minute.','Geysers are usually set to about 60 \u00B0C. Above that, scalding risk goes up. Below about 60 \u00B0C, bacteria risk goes up.','Electrician checks and sets the thermostat. A faulty thermostat is replaced.','Fit a thermostatic mixing valve for showers and baths where scald risk is a worry.','Check the safety valve works and its drain is clear.','Tell the customer the safe temperature and what you changed.'],
  sans:['SANS 10254 covers fixed electric storage water heaters including safety devices. Check the current standard for the temperature limits where children or elderly people use the water.']}},
{id:'pump-not-starting',title:'Pump not starting',kw:'pump not starting booster pump jockey tank pressure switch dry run prime breaker',sum:'Booster or tank pump will not run, or runs and gives no water',
 diagnose:{start:'q1',nodes:{
  q1:{q:'What does the pump do?',opts:[['Nothing (no sound, no light)','q_pow'],['Hums but does not turn','r_stuck'],['Runs but delivers no water or very little','q_prime'],['Starts and stops again and again','r_cycle']]},
  q_pow:{q:'Is there power at the plug or DB, and is the pump breaker on?',opts:[['No power / breaker tripped','r_power'],['Power is on','r_switch']]},
  q_prime:{q:'Is the tank or water source empty, or is there air in the suction pipe?',opts:[['Tank empty','r_dry'],['Source has water','r_prime']]},
  r_power:{res:1,cause:'No power to the pump',do:['Check the plug, extension lead, breaker and earth leakage.','Reset a tripped breaker once only. If it trips again call an electrician.'],call:'electrician'},
  r_switch:{res:1,cause:'Pressure switch or controller fault',do:['Check the pressure switch settings and contacts.','Check the controller error lights.','Electrician checks the pump motor and capacitor.'],call:'electrician',parts:[['Water pumps','water pump']],next:'repair'},
  r_stuck:{res:1,cause:'Seized impeller or a failed capacitor',do:['Switch off at the DB. Check the pump turns by hand at the fan end (if designed so).','Electrician checks the capacitor and motor.'],call:'electrician',next:'repair'},
  r_dry:{res:1,cause:'Dry running. Stop the pump to protect the seal',do:['Switch the pump off.','Fix the water supply to the tank.','Prime the pump before restarting.'],next:'repair'},
  r_prime:{res:1,cause:'Pump lost its prime or air is in the suction pipe',do:['Switch off. Fill the pump body through the priming plug.','Check the suction pipe joints are airtight and the foot valve seals.','Restart and check flow.'],parts:[['Non-return valve','non return valve']],next:'repair'},
  r_cycle:{res:1,cause:'Short cycling: waterlogged pressure vessel, leak, or a faulty non-return valve',do:['Check the pressure vessel air charge.','Check for leaks in the pipes and at the taps.','Check the non-return valve.'],parts:[['Pressure gauge','pressure gauge'],['Non-return valve','non return valve']],next:'repair'}
 }},
 repair:{warn:['Pump wiring and motor repairs: registered electrician only.'],tools:['Spanners','PTFE tape','Pressure gauge','Torch','Bucket'],parts:[['Water pumps','water pump'],['Non-return valve','non return valve'],['Pressure gauge','pressure gauge']],
  steps:['Switch the pump off at the plug or DB.','Check there is water at the source. Never run a pump dry.','Check the power: plug, lead, breaker and earth leakage.','Prime the pump: fill the body through the priming plug and check the suction pipe is airtight.','Check the pressure switch settings and the vessel air charge.','Check the non-return valve and the foot valve.','Restart. Watch the pressure and the cycle for a few minutes. Note what was done.'],
  sans:['SANS 10252-1: a pump supplying a building must not allow back-flow into the municipal main. Check the correct backflow protection.']}},
{id:'meter-running',title:'Water meter running with taps off',kw:'water meter running leak hidden leak bill high toilet geyser irrigation meter test pressure drop',sum:'Find a hidden leak with the meter test',
 diagnose:{start:'q1',nodes:{
  q1:{q:'Close every tap and appliance. Is the meter dial (or the small low-flow indicator) moving?',opts:[['Yes, it is moving','q2'],['No, it is still','r_none']]},
  q2:{q:'Close the main valve at the house. Does the meter still move?',opts:[['Yes, still moving','r_meter'],['It stops, so the leak is in the house or garden','q3']]},
  q3:{q:'Close the geyser cold-feed valve. Does the meter stop?',opts:[['Yes, it stops','r_geyser'],['No, still moving','q4']]},
  q4:{q:'Close the garden / irrigation line. Does it stop?',opts:[['Yes','r_garden'],['No','q5']]},
  q5:{q:'Add food colouring to each cistern. Is there colour in a bowl after 10 minutes?',opts:[['Yes','r_wc'],['No','r_hidden']]},
  r_none:{res:1,cause:'No leak at the moment',do:['Check again at a quiet time (the leak may be intermittent).','Check the bill: an estimated reading or a change in use can explain it.'],call:'municipality'},
  r_meter:{res:1,cause:'The meter itself or the pipe before the house valve',do:['Check the meter and the pipe between the meter and the valve for a leak.','Report a faulty meter to the municipality.'],call:'municipality'},
  r_geyser:{res:1,cause:'Leak on the hot side: geyser, safety valve or hot pipes',do:['Check the safety valve drain, the drip tray, the roof space and the hot pipes.','Look for wet ceilings and warm floors.'],next:'repair'},
  r_garden:{res:1,cause:'Leak in the garden or irrigation',do:['Check taps, hoses and irrigation valves.','Look for wet patches and trace the line.'],next:'repair'},
  r_wc:{res:1,cause:'A toilet is leaking into the bowl',do:['Replace the flush valve seal or the fill valve.'],parts:[['Flush valve','flush valve'],['Fill valve','fill valve']],next:'repair'},
  r_hidden:{res:1,cause:'Hidden leak in the cold supply pipes (slab, wall or underground)',do:['Isolate sections to narrow it down.','Pressure test the isolated section.','Use a listening device or a leak detection service.','Open up as little as possible.'],next:'repair'}
 }},
 repair:{tools:['Pressure gauge','Isolating key','Food colouring','Torch','Listening device (if available)','Camera'],parts:[['Pressure gauge','pressure gauge'],['Repair coupling','repair coupling'],['Isolating valve','ball valve']],
  steps:['Ask: where and when did the leak start? Any change in the bill? Any sound of running water?','Close every tap and appliance. Read the meter and note the digits and the low-flow indicator.','Close the main valve at the house. If the meter still moves, the leak is before the house valve.','Isolate sections one at a time (geyser, garden, house) and watch the meter.','Check the usual suspects: toilets (food colouring test), dripping taps, geyser safety-valve drain, outside taps and irrigation.','Pressure test the leaking section with a gauge and look for a drop.','Pinpoint: look for damp, stains, warm floor patches (hot pipe); listen; use a moisture meter or thermal camera.','Open up as little as possible. Take photos. Repair, pressure test for at least 15 minutes and re-check the meter.'],
  sans:['SANS 10252-1: new or repaired water pipes should be tested under pressure before being covered.']}},
{id:'geyser-install',title:'Geyser installation / replacement',kw:'geyser installation replace new install drip tray safety valve t&p vacuum breaker pressure control valve certificate coc insulation base',sum:'Replace an electric geyser (indoor roof or outside)',
 install:{warn:[ELEC_WARN,'Working in the roof space: step only on trusses or a board, with a head torch, and tell someone you are up there. Two people to lift the geyser.'],
  tools:['Two people to lift','Ladder, torch / head-lamp','Spanners and adjustable spanners','Pipe cutter, hacksaw','Pressure gauge','Hose and bucket','PTFE tape and new connectors','Spirit level','Camera for photos'],
  parts:[['Geyser','geyser 150l'],['Safety (T&P) valve','safety valve'],['Vacuum breaker','vacuum breaker'],['Pressure control valve','pressure control valve'],['Non-return valve','non return valve'],['Isolating valve','ball valve 22mm'],['Drip tray','geyser tray'],['Geyser connectors','geyser connector'],['Pipe lagging','lagging'],['Copper pipe 22mm','copper pipe 22mm'],['22mm elbow','22mm elbow']],
  steps:['Check the old geyser: size (litres), pressure rating (kPa) and type. Photograph the data plate. Check supply pressure with a gauge.','Switch off the geyser breaker at the DB and the isolator. Label it. Test it is dead (electrician).','Close the cold feed isolating valve. Open a hot tap in the house to relieve pressure.','Drain the geyser through the drain cock or a hose to a safe place. The water may be scalding: let it cool or draw hot water off first.','Disconnect the pipes and the safety valve drain. The electrician disconnects the wiring. Lift the geyser out with two people.','Check the drip tray and its drain pipe. It must be bigger than the geyser, level, and drain with a fall to a visible, safe outside point. Replace it if rusty or cracked.','Set the new geyser on a solid base or secure brackets that carry the full weight (a full 150 L geyser weighs about 170 kg).','Fit the valves in the order the maker shows: isolating valve, non-return valve, pressure control valve if supply pressure is above the geyser rating, vacuum breaker(s) above the top of the geyser, and the T&P safety valve on the geyser safety port.','Connect the safety valve drain: metal, at least the valve size, continuous fall, no more than 3 bends, discharging to a visible place outside. No valve or cap in it.','Connect cold in and hot out to the correct ports with new connectors. Insulate the hot pipe and the geyser as required.','Fill slowly with a hot tap open until water runs without air. Close the tap. Check every joint for leaks.','Only when the geyser is full: the electrician reconnects and switches on (Electrical CoC). Set the thermostat (usually about 60 \u00B0C).','Check the safety valve drain for drips. Briefly lift the valve lever: water must flow and then stop.','Take photos. Complete the plumbing Certificate of Compliance if required (licensed plumber).','Hand over: show the customer the isolating valve and the DB switch.'],
  sans:['SANS 10254 covers the installation of fixed electric storage water heaters. Follow it and the geyser maker\u2019s instructions.','Safety valve drain: metal, at least the valve outlet size, continuous fall (no upward sections), no more than 3 bends, discharging where it can be seen outside, and no valve, cap or plug in it.','Fit a drip tray with its own drain where a leak can cause damage.','A plumbing CoC can only be issued by a licensed (PIRB) plumber. Insurers often ask for it when a geyser is replaced. The Electrical CoC is the electrician\u2019s.']}},
{id:'basin-mixer-replace',title:'Basin / mixer replacement',kw:'basin mixer replace tap pedestal angle valves flexi trap waste install tile wall bracket',sum:'Replace a pedestal basin, mixer, angle valves, flexis, waste and trap',
 install:{warn:['Tiled walls and floors: use the right masonry bit and go slowly (no hammer action on tile). Basins are heavy: fix to a solid wall or board, not to drywall alone.'],
  tools:['Basin spanner','Adjustable spanners','Drill and tile / masonry bits','Spirit level','Tape measure','Screwdrivers','Silicone gun','Bucket and towels','PTFE tape'],
  parts:[['Basin','basin'],['Pedestal','pedestal'],['Basin mixer','basin mixer'],['Angle valves','angle valve'],['Flexi hoses','flexi'],['Basin waste','basin waste'],['Trap','basin trap'],['Fixing bolts','basin fixing'],['Silicone','silicone'],['PTFE tape','ptfe tape']],
  steps:['Close the water (angle valves or room valve). Open the old tap to release pressure.','Put a bucket and towels down. Disconnect the flexi hoses, the trap and the waste. Remove the old basin and pedestal.','Check the wall and floor: solid fixing needed. Mark the position (rim about 800 to 850 mm above the floor), check level and where the waste outlet comes out of the wall or floor.','Fit the tap and the waste to the basin before mounting it. Fit new angle valves on the supply pipes (PTFE on threads).','Mount the basin level: drill the wall fixings (tile bit first, then masonry bit), use correct plugs and bolts. Set the pedestal on the floor and fix it. Do not over-tighten (porcelain cracks).','Connect new flexi hoses to the mixer and angle valves: hot on the left, cold on the right. Do not kink them.','Connect the trap and the waste pipe with a fall to the waste outlet.','Flush the supply lines into a bucket before connecting the hoses to the tap (debris damages the cartridge).','Open the angle valves slowly. Check every joint for leaks, wipe dry and check again after 10 minutes.','Fill the basin and let it run out: check the trap and waste joints. Seal the basin to the wall with silicone. Clean and remove protective plastic.','Show the customer the angle valves.'],
  sans:['SANS 10252-1: an isolating (angle) valve at each fixture is good practice. Use new flexi hoses.','SANS 10252-2: trap fitted and holds its water seal; waste falls at least 1:46 (waste branch); trap outlet not more than 6 m of pipe from a vent.','Check the tap suits the pressure system (low-pressure taps for gravity-fed geysers).']},
 repair:{tools:['Basin spanner','Adjustable spanner','Screwdrivers','Bucket and towel','PTFE tape'],parts:[['Basin mixer','basin mixer'],['Cartridge','mixer cartridge'],['Flexi hoses','flexi'],['Angle valves','angle valve']],
  steps:['Close the angle valves. Open the tap to release pressure.','Disconnect the flexi hoses. Undo the fixing nut with a basin spanner and lift out the old mixer.','Clean the surface. Check the new mixer suits the hole size and the pressure system.','Fit the new mixer with its washers. Do not over-tighten the fixing nut (ceramic can crack).','Fit new flexi hoses. Flush the lines into a bucket first. Connect and open the valves slowly.','Test hot and cold, check every joint dry after 10 minutes.'],
  sans:['SANS 10252-1: isolating valve at each fixture; use new flexi hoses.'],see:['basin-mixer-replace','install','Full basin replacement steps are on the Install tab']}},
{id:'toilet-pan-replace',title:'Toilet pan replacement',kw:'toilet pan wc replace install cistern connector p-trap s-trap close coupled floor fixing flush angle valve flexi',sum:'Replace a toilet pan and cistern',
 install:{warn:['Porcelain cracks if over-tightened. Wear waterproof gloves and glasses. Lift with care: pans and cisterns are heavy.'],
  tools:['Adjustable spanners','Screwdrivers','Drill and bits for the floor','Spirit level','Silicone gun','Bucket, sponge and towels','Gloves and glasses'],
  parts:[['WC pan','toilet pan'],['Close-coupled cistern','cistern'],['WC connector','wc connector'],['Fill valve','fill valve'],['Flush valve','flush valve'],['Angle valve','angle valve'],['Flexi hose','flexi'],['Pan fixing kit','pan fixing'],['Silicone','silicone']],
  steps:['Close the angle valve. Flush to empty the cistern and sponge out the rest. Disconnect the flexi hose.','Unscrew the cistern bolts and lift the cistern off. Unscrew the pan from the floor and break the seal at the outlet. Lift the pan away. Block the open pipe with a rag (sewer gas).','Check the outlet type: P-trap (to the wall) or S-trap (to the floor) and the distance from the wall to the centre of the outlet. The new pan must match.','Check the floor is flat and the soil pipe end is clean and undamaged.','Fit the WC connector or push-fit soil connection to the 110 mm drain. Clean the pipe end and lubricate the seal.','Set the pan, mark and drill the floor fixings. Use plugs suited to the floor. Fix with the correct bolts and washers. Do not over-tighten.','Fit the cistern (close-coupled: seal and bolts; wall-hung: bracket and flush pipe).','Fit a new angle valve and flexi hose to the cistern inlet.','Open the angle valve. Flush several times. Check the water level, fill valve cut-off, flush volume and every joint for leaks.','Check the pan outlet seal and trap: no leaks and the trap holds water in the bowl.','Seal around the base with sanitary silicone if the customer wants it. Clean and show the customer the angle valve.'],
  sans:['SANS 10252-2: the pan trap holds its water seal; soil pipe falls at least 1:40 (soil branch) with no flat or backward sections; the trap outlet is not more than 6 m of pipe from a ventilated stack or drain.','SANS 10252-1: an isolating (angle) valve at the cistern, and an overflow that discharges safely.']}}
];
